// Function to run the recommendation API
public static HashMap<string, string> RecommendProductsToUser(string searchText, int maxResults, int weight, string state)
{
    // Create XML document to send request to recommendation service
    XmlDocument docXltmltxt;
    docXltmltxt = XmlUtils.CreateXml(XmlConstants.XmlDir + "/getRecommendations.xml", {});
    docXltmltxt.SetElement(XmlConstants.RootElement, XmlUtils.CreateNodeFromDictionary({"UserQuery":searchText, "UserWeight":weight, "MaxRecommendationNumber":maxResults, "State":state}));
    // Send XML document to recommendation service
    XmlUtils.SaveXmlToFile(docXltmltxt, "recommendationService.xml");
    // Call recommendation service to get product recommendations
    XmlUtils.ReadXmlFromFile("recommendationService.xml");
    // Close XML document
    XmlUtils.CloseXml(docXltmltxt);
    // Return product recommendations
    return Product.objects
               .Where(p => searchText.ToLower().Contains(p.ToString().ToLower())
                    .GroupBy(p => p.ToString().ToLower())

